package pe.edu.upc.ice.track.platform.service.request.interfaces.rest.resources;

import io.swagger.v3.oas.annotations.media.ArraySchema;
import io.swagger.v3.oas.annotations.media.Schema;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;
import jakarta.validation.constraints.Size;

import java.time.Instant;
import java.util.List;
import java.util.UUID;

/**
 * Resource received to register the intervention that completes a service request.
 *
 * <p>{@code client_generated_id} is generated by the technician's device before the first attempt
 * and kept for every retry: it is what lets the server answer a retried submission with the
 * intervention it already registered instead of a conflict.</p>
 */
@Schema(
    name = "RegisterInterventionRequest",
    description = "Intervention registration request",
    example = "{\"service_request_id\": 42, \"client_generated_id\": \"3f2b8c1e-6a4d-4e0b-9a51-2c7d8e9f0a1b\", "
        + "\"diagnosis\": \"Compressor relay burnt\", \"actions_taken\": \"Replaced the start relay and tested the cycle\", "
        + "\"spare_parts\": [\"Start relay 4TM\"], \"photo_evidence\": [\"https://cdn.example.com/photos/42-1.jpg\"], "
        + "\"completed_at\": \"2026-10-23T16:30:00Z\"}")
public record RegisterInterventionResource(
    @NotNull(message = "{validation.not-null}")
    @Positive(message = "{validation.positive}")
    @Schema(description = "Identifier of the service request the intervention completes", example = "42")
    Long serviceRequestId,

    @NotNull(message = "{validation.not-null}")
    @Schema(description = "UUID generated by the technician's device, kept across retries", example = "3f2b8c1e-6a4d-4e0b-9a51-2c7d8e9f0a1b")
    UUID clientGeneratedId,

    @NotBlank(message = "{validation.not-blank}")
    @Size(max = 2000, message = "{validation.size.max}")
    @Schema(description = "What the technician found", example = "Compressor relay burnt", maxLength = 2000)
    String diagnosis,

    @NotBlank(message = "{validation.not-blank}")
    @Size(max = 2000, message = "{validation.size.max}")
    @Schema(description = "What the technician did", example = "Replaced the start relay and tested the cycle", maxLength = 2000)
    String actionsTaken,

    @Size(max = 50)
    @ArraySchema(
        arraySchema = @Schema(description = "Spare parts used, at most 50", nullable = true),
        schema = @Schema(example = "Start relay 4TM", maxLength = 100))
    List<@NotBlank(message = "{validation.not-blank}") @Size(max = 100, message = "{validation.size.max}") String> spareParts,

    @Size(max = 20)
    @ArraySchema(
        arraySchema = @Schema(description = "References (URLs or storage keys) of the photos taken, at most 20", nullable = true),
        schema = @Schema(example = "https://cdn.example.com/photos/42-1.jpg", maxLength = 2048))
    List<@NotBlank(message = "{validation.not-blank}") @Size(max = 2048, message = "{validation.size.max}") String> photoEvidence,

    @Schema(
        description = "When the work finished according to the technician's device, ISO-8601; "
            + "the server clock is used when absent",
        example = "2026-10-23T16:30:00Z",
        nullable = true)
    Instant completedAt
) {
}
